  public function validateCampo($campo,$unidad_documental)
  {
    $c = new Criteria();
    $c->add(DescripcionArchivosPeer::UNIDADDOCUMENTAL_ID,$unidad_documental);
    $c->add(DescripcionArchivosPeer::CAMPOSAREASDESCRIPCION_ID,$campo);
    $count_val = DescripcionArchivosPeer::doSelectOne($c);
    if($count_val != null){
       return $count_val->getPrimaryKey();
    }else{
        return 0;
    }
  }
  
